/**
 * AmaliTech Alert — contextual feedback banner.
 *
 * Mirrors the Unified Experience Design "Alert" Figma component:
 *   Color : 'success' | 'info' | 'warning' | 'default' | 'danger'
 *   Mode  : 'light' (default) | 'dark' (charcoal) | 'dark-blue' (brand navy)
 *   + toggles: heading, left icon, right (close) icon, body text, button.
 *
 * Self-contained — inlines its own icon set, no Icon dependency.
 */

// semantic color -> token ramp
const RAMP = {
  success: 'green',
  danger: 'red',
  info: 'light-blue',
  warning: 'yellow',
  default: 'gray'
};

// "View more" button fill. Success/danger/warning keep their color across modes;
// the navy (info/default) fill switches to the orange brand accent on dark surfaces
// so it stays legible against the dark background.
function buttonStyle(color, mode) {
  if (color === 'success') return ['var(--green-700)', 'var(--white)'];
  if (color === 'danger') return ['var(--red-700)', 'var(--white)'];
  if (color === 'warning') return ['var(--yellow-400)', 'var(--gray-800)'];
  // info & default
  return mode === 'light' ? ['var(--dark-blue-500)', 'var(--white)'] : ['var(--orange-700)', 'var(--white)'];
}
